parameters.jsCode:
// Accedemos al nodo de lectura más reciente
const datosActuales = $node["Leer_Datos_Finales"].json;

// Generamos el ID de ticket
const ticketId = "TK-" + Math.floor(Math.random() * 9000 + 1000);

// Obtenemos la fecha y hora actual en formato local (Colombia)
const ahora = new Date();
const fechaCreacion = ahora.toLocaleDateString('es-CO') + " " + ahora.toLocaleTimeString('es-CO', { hour12: false });

// Retornamos el objeto con las nuevas columnas
return {
  ticket_id: ticketId,
  fecha_creacion: fechaCreacion,
  creado_por: datosActuales.nombre || datosActuales.telegram_user, // Usa el nombre, si no existe, el ID
  telegram_id: datosActuales.telegram_user,
  tipo: datosActuales.temp_tipo,
  prioridad: datosActuales.temp_prioridad,
  descripcion: datosActuales.temp_desc,
  estado: "Abierto"
};

const items = $input.all();
if (!items || items.length === 0 || !items[0].json.id_ticket) {
  return [{json: {mensaje: '📭 No tienes solicitudes registradas todavía.\n\nEscribe 1 para crear una nueva solicitud.'}}];
}
let msg = `📝 Tus solicitudes (${items.length} total):\n\n`;
for (const item of items) {
  const t = item.json;
  const estado = t.estado === 'Abierto' ? '🟢' : t.estado === 'En proceso' ? '🟡' : '🔴';
  msg += `🎫 ${t.id_ticket}\n${estado} ${t.estado} | 📌 ${t.tipo} | ⚡ ${t.prioridad}\n📅 ${String(t.fecha_creacion).substring(0,10)}\n\n`;
}
msg += 'Escribe 2 para consultar el detalle de un ticket por su ID.';
return [{json: {mensaje: msg}}];
